def transform(g):
    h,w=len(g),len(g[0])
    c4=[(r,c) for r in range(h) for c in range(w) if g[r][c]==4]
    c6=[(r,c) for r in range(h) for c in range(w) if g[r][c]==6]
    top=min(r for r,c in c4); bottom=max(r for r,c in c4)
    left=min(c for r,c in c4); right=max(c for r,c in c4)
    r6a,r6b=min(r for r,_ in c6),max(r for r,_ in c6)
    l6,r6=min(c for _,c in c6),max(c for _,c in c6)
    T6=[[g[r][c] for c in range(l6,r6+1)] for r in range(r6a,r6b+1)]
    sym_h = T6 == T6[::-1]
    sub=[row[left:right+1] for row in g[top:bottom+1]]
    out=[[0 if v==6 else v for v in row] for row in g]
    if sym_h:
        for i,row in enumerate(sub[::-1]):
            rr = bottom+1+i if r6a>bottom else top-1-(len(sub)-1-i)
            if 0<=rr<h:
                for j,v in enumerate(row):
                    if v: out[rr][left+j]=v
    else:
        m6 = l6 > right
        for i in range(len(sub)):
            for j,v in enumerate(sub[i]):
                if not v: continue
                cc = 2*right+1-left-j if m6 else left-1-j
                if 0<=cc<w: out[top+i][cc]=v
    return out
